// Detailed village assets retain the planned streets and existing service positions.
const ARTISAN_BUILDINGS={smith:{file:'forge-clean-v24.png',ratio:1024/1536,extra:100},alchemist:{file:'alchemist-v24.png',ratio:1086/1448,extra:115},merchant:{file:'merchant-v24.png',ratio:1086/1448,extra:100},healer:{file:'healer-v24.png',ratio:1086/1448,extra:100}};
for(const a of Object.values(ARTISAN_BUILDINGS)){a.image=document.createElement('img');a.image.src='assets/'+a.file}
function artisanBuildingRect(b){const a=ARTISAN_BUILDINGS[b.id],w=b.w+a.extra,h=w*a.ratio;return{x:b.x-28,y:b.y+b.h+18-h,w,h}}
const houseBeforeArtisans=house;house=function(b){const a=ARTISAN_BUILDINGS[b.id];if(!a?.image.complete||!a.image.naturalWidth)return houseBeforeArtisans(b);const r=artisanBuildingRect(b),behind=p.x>b.x-8&&p.x<b.x+b.w+35&&p.y>b.y-150&&p.y<b.y+b.h;ctx.save();ctx.imageSmoothingEnabled=false;if(behind)ctx.globalAlpha=.35;ctx.drawImage(a.image,Math.round(r.x),Math.round(r.y),Math.round(r.w),Math.round(r.h));ctx.restore();label(b.name,b.x+b.w/2,r.y-18,'#f1d4a2',12);
 if(b.id==='smith'){const x=r.x+r.w*.69,y=r.y+r.h*.72;glow(x,y,32+Math.sin(time*6)*3,'#ed9a4225');if(Math.sin(time*4)>.5){rect(x-3,y-5,2,2,'#ffe19b');rect(x+6,y-12,2,3,'#efac62')}}
 if(b.id==='alchemist'){const x=r.x+r.w*.76,y=r.y+r.h*.79;glow(x,y,22,'#63d8c820');for(let n=0;n<3;n++){const f=(time*9+n*13)%40;disc(x+Math.sin(f*.2+n)*7,y-f,1.5,'#9be1cf88')}}
};

