npcSprites.delete('alchemist');
const npcBeforeArtisans=drawNpc;drawNpc=function(s){npcBeforeArtisans(s);if(s.id==='alchemist'){for(let n=0;n<3;n++){const f=(time*13+n*9)%25;disc(s.x+26+Math.sin(f*.4+n)*3,s.y-28-f,1,'#a6e5d4aa')}}};
npcInfo.alchemist='Luma · Ayışığı simyacısı ve iksir ustası';npcInfo.merchant='Nara · Rüzgâr Pazarı’nın ganimet tüccarı';npcInfo.healer='Mira · Kök Sığınağı’nın bitki şifacısı';
const VILLAGE_CONVERSATIONS={
 alchemist:{title:'Luma · Ayışığı Simyacısı',text:'Bir tutam öz, bir parça kristal… Gerisi doğru ölçü, gezgin. Ganimetlerini işe yarar iksirlere dönüştürelim.',actions:[['recipes','⚗','İksir üret','Tarifleri ve gereken malzemeleri incele.']]},
 merchant:{title:'Nara · Rüzgâr Pazarı',text:'Hoş geldin, gezgin. Çantandaki ganimetlere bakalım; yola çıkmadan erzağını da tamamlayabilirsin.',actions:[['trade','◆','Ganimet sat','Satılabilir eşyalarını ve fiyatlarını gör.'],['supply','✚','İksir ve erzak al','Can, enerji ve savaş iksirleri.']]},
 healer:{title:'Mira · Köklerin Şifacısı',text:'Biraz soluklan. Kök Sığınağı’nda her yolcunun dinlenmeye hakkı var. Yaralarını birlikte iyileştirelim.',actions:[['healing','❧','Şifa hizmetleri','Canını yenile ve yeniden yola koyul.']]}
};
let villageConversation='welcome';
const openBeforeArtisanTalk=openService;openService=function(id){if(VILLAGE_CONVERSATIONS[id])villageConversation='welcome';openBeforeArtisanTalk(id)};
function chooseArtisanAction(action){const id=$('service').dataset.kind,q=VILLAGE_CONVERSATIONS[id];if(!q||p.area!=='hub'||!$('service').open||nearestService()?.id!==id)return false;if(action==='leave'){$('service').close();keys={};return true}if(action!=='welcome'&&!q.actions.some(a=>a[0]===action))return false;villageConversation=action;if(id==='merchant'&&action!=='welcome')npcActiveTab=action;renderService();$('service').scrollTop=0;return true}
const renderBeforeArtisanTalk=renderService;renderService=function(){const id=$('service').dataset.kind,q=VILLAGE_CONVERSATIONS[id],welcome=q&&villageConversation==='welcome';$('service').classList.toggle('artisan-talk',!!welcome);if(!welcome){renderBeforeArtisanTalk();if(q){$('serviceBody').insertAdjacentHTML('afterbegin','<button id="artisanBack" class="boran-back">← Konuşmaya dön</button>');$('artisanBack').onclick=()=>chooseArtisanAction('welcome')}return}
 $('service').classList.toggle('boran-talk',false);$('service').classList.toggle('smith-open',false);$('serviceTitle').textContent=q.title;$('serviceGold').textContent=p.gold+' altın';drawServicePortrait(services.find(s=>s.id===id));
 $('serviceBody').innerHTML=`<div class="artisan-conversation"><div class="artisan-card"><img src="assets/${ARTISAN_BUILDINGS[id].file}" alt="${buildings.find(b=>b.id===id).name}"><div><canvas id="artisanPortrait" width="144" height="200" aria-label="${q.title}"></canvas><span>${q.title}</span></div></div><nav class="boran-options" aria-label="Konuşma seçenekleri"><small>NE YAPMAK İSTERSİN?</small>${q.actions.map(([key,icon,name,detail])=>`<button data-artisan="${key}"><i>${icon}</i><span>${name}<small>${detail}</small></span><b>›</b></button>`).join('')}<button data-artisan="leave"><i>↩</i><span>Hoşça kal<small>Köye geri dön.</small></span><b>›</b></button></nav><div class="boran-speech"><b>${q.title}</b><p>${q.text}</p><small>Bir işlem seç · ESC ile ayrıl</small></div></div>`;
 const c=$('artisanPortrait'),g=c.getContext('2d');g.imageSmoothingEnabled=false;if(id==='alchemist'&&lumaArt.complete&&lumaArt.naturalWidth)g.drawImage(lumaArt,6,0,132,200);else g.drawImage(npcSprites.get(id)||makeNpcSprite(id),0,0,144,200);$('serviceBody').querySelectorAll('[data-artisan]').forEach(b=>b.onclick=()=>chooseArtisanAction(b.dataset.artisan));
};
